import { options as _options } from 'preact';

// Cast to use internal Options type
const options = /** @type {import('./internal').Options} */ (_options);

const RAF_TIMEOUT = 100;
const HAS_RAF = typeof requestAnimationFrame == 'function';
const deferUpdate =
	typeof Promise == 'function'
		? Promise.prototype.then.bind(Promise.resolve())
		: setTimeout;

/**
* Coordinates hook state, root rendering, component updates and vnode cloning.
* @constructor
*/
class HookRuntime {
	constructor() {
		this.sessionIndex = 0;
		this.sessionComponent = null;
		this.sessionPrevious = null;
		this.sessionHook = 0;
		this.emptyList = [];
		this.paintQueue = [];
		this.paintRaf = undefined;
		this.oldBeforeDiff = options._diff;
		this.oldBeforeRender = options._render;
		this.oldAfterDiff = options.diffed;
		this.oldCommit = options._commit;
		this.oldBeforeUnmount = options.unmount;
		this.oldRoot = options._root;
		this.renderHydrating = false;
		this.renderOldVNode = null;
		this.renderCommitQueue = null;
		this.renderRefQueue = null;
		this.renderDeps = null;
		this.updateQueue = [];
		this.updateCount = 0;
		this.prevDebounce = undefined;
		this.componentDeps = null;
		this.cloneProps = null;
		this.cloneKey = undefined;
		this.cloneRef = undefined;
		this.rootVnode = null;
		this.rootHost = null;
		this.rootMaskSeen = 0;
		this.rootKind = '';
	}

	install() {
		options._diff = vnode => this.handleBeforeDiff(vnode);
		options._render = vnode => this.handleRender(vnode);
		options.diffed = vnode => this.handleDiffed(vnode);
		options._commit = (vnode, commitQueue) =>
			this.handleCommit(vnode, commitQueue);
		options.unmount = vnode => this.handleUnmount(vnode);
		options._root = (vnode, parentDom) => this.handleRoot(vnode, parentDom);
		options._hookRuntime = this;
	}

	handleBeforeDiff(vnode) {
		this.sessionComponent = null;
		if (this.oldBeforeDiff) this.oldBeforeDiff(vnode);
	}

	handleRender(vnode) {
		if (this.oldBeforeRender) this.oldBeforeRender(vnode);

		this.sessionComponent = vnode._component;
		this.sessionIndex = 0;

		const hooks = this.loadSessionHooks();
		if (hooks) {
			this.hookListLength(this.sessionComponent);
			this.pendingEffectCount(this.sessionComponent);
			if (this.sessionPrevious === this.sessionComponent) {
				this.resetPendingHookValues(hooks);
			} else {
				this.replayPendingEffects(hooks);
			}
		}
		this.syncPreviousComponent();
	}

	handleDiffed(vnode) {
		const _paintQueue = this.paintQueue;
		if (this.oldAfterDiff) this.oldAfterDiff(vnode);

